valuesYaml:
externalUrl: https://${APP_HOST}
oidc:
  enabled: true
  issuerUrl: ${OIDC_ISSUER_URL}/.well-known/openid-configuration
  clientId: ${OIDC_CLIENT_ID}
  clientSecret: ${OIDC_CLIENT_SECRET}
  tokenAuthMethod: client_secret_basic
ingress:
  enabled: true
  host: ${APP_HOST}
  forwardAuth: ${FORWARD_AUTH}
